public static Object generateValue(
      String tableName,
      DataGeneratorColumn column,
      Faker faker,
      CustomDataGenerator customGenerator) {
    if (customGenerator != null) {
      try {
        Object customValue = customGenerator.generate(tableName, column.name());
        if (customValue != null) {
          if (CustomDataGenerator.EXPLICIT_NULL.equals(customValue)) {
            return null;
          }
          return customValue;
        }
      } catch (Exception e) {
        throw new RuntimeException(
            "CustomDataGenerator failed for table '"
                + tableName
                + "' column '"
                + column.name()
                + "'",
            e);
      }
    }
    LogicalType type = column.logicalType();
    Long size = column.size();
    if (column.fakerExpression() != null) {
      Object override = column.fakerExpression();
      if (override instanceof String) {
        return generateFromStringExpression((String) override, column, faker);
      }
      if (type == LogicalType.JSON) {
        try {
          Object resolvedTree = resolveJsonTemplateNode(override, faker);
          return MAPPER.writeValueAsString(resolvedTree);
        } catch (Exception e) {
          throw new RuntimeException(
              "Failed to serialize nested JSON override for column " + column.name(), e);
        }
      }
      throw new IllegalArgumentException(
          "Unsupported nested override for non-JSON column '" + column.name() + "'.");
    } else {
      switch (type) {
        case STRING:
          return faker.lorem().characters(limitStringLength(size));
        case JSON:
          return "{"
              + "\"id\": "
              + faker.number().randomNumber()
              + ", "
              + "\"name\": \""
              + faker.name().fullName()
              + "\", "
              + "\"isActive\": "
              + faker.bool().bool()
              + ", "
              + "\"score\": "
              + faker.number().randomDouble(2, 0, 100)
              + ", "
              + "\"tags\": [\""
              + faker.lorem().word()
              + "\", \""
              + faker.lorem().word()
              + "\"], "
              + "\"address\": {\"city\": \""
              + faker.address().city()
              + "\", \"zip\": \""
              + faker.address().zipCode()
              + "\"}"
              + "}";
        case UUID:
          return UUID.randomUUID().toString();
        case INT64:
          return (long) ThreadLocalRandom.current().nextInt();
        case FLOAT64:
          {
            int scale = column.scale() != null ? column.scale() : Constants.DEFAULT_NUMERIC_SCALE;
            int precision =
                column.precision() != null
                    ? column.precision()
                    : Constants.DEFAULT_NUMERIC_PRECISION + 5;
            double maxVal = Math.pow(10, precision - scale) - 1.0 / Math.pow(10, scale);
            double minVal = -maxVal;
            return faker.number().randomDouble(scale, (long) minVal, (long) maxVal);
          }
        case NUMERIC:
          return generateNumeric(column, faker);
        case BOOLEAN:
          return faker.bool().bool();
        case BYTES:
          return faker.lorem().characters(limitStringLength(size)).getBytes(StandardCharsets.UTF_8);
        case DATE:
          {
            long minMillis = 157766400000L; // Year 1975
            long maxMillis = 2051222400000L; // Year 2035
            long randomMillis = ThreadLocalRandom.current().nextLong(minMillis, maxMillis);
            Calendar cal = Calendar.getInstance();
            cal.setTimeInMillis(randomMillis);
            // Zero the time part — DATE is day-granular and TIMESTAMP uses the TIMESTAMP branch.
            cal.set(Calendar.HOUR_OF_DAY, 0);
            cal.set(Calendar.MINUTE, 0);
            cal.set(Calendar.SECOND, 0);
            cal.set(Calendar.MILLISECOND, 0);
            return new Instant(cal.getTimeInMillis());
          }
        case TIMESTAMP:
          {
            long minMillis = 157766400000L; // Year 1975
            long maxMillis = 2051222400000L; // Year 2035
            return new Instant(ThreadLocalRandom.current().nextLong(minMillis, maxMillis));
          }
        default:
          throw new UnsupportedOperationException(
              "Unsupported logical type for dynamic data generation: " + type);
      }
    }
  }

@Override
  public ImmutableMap<String, ImmutableList<SourceColumnIndexInfo>> discoverTableIndexes(
      DataSource dataSource,
      JdbcSchemaReference sourceSchemaReference,
      ImmutableList<String> tables)
      throws SchemaDiscoveryException, RetriableSchemaDiscoveryException {
    if (tables.isEmpty()) {
      return ImmutableMap.of();
    }
    logger.info(
        "Discovering Indexes for DataSource: {}, JdbcSchemaReference: {}, Tables: {}",
        dataSource,
        sourceSchemaReference,
        tables);

    // https://www.db-fiddle.com/f/eUSGErdEWNQL8FhMj99Kb7/0
    final String query =
        "SELECT ixs.tablename AS table_name,"
            + "  a.attname AS column_name,"
            + "  ixs.indexname AS index_name,"
            + "  ix.indisunique AS is_unique,"
            + "  ix.indisprimary AS is_primary,"
            + "("
            + "SELECT SUM(pc.reltuples)"
            + " FROM pg_catalog.pg_class pc"
            + "  WHERE pc.oid IN ("
            + "  SELECT inhrelid FROM pg_catalog.pg_inherits WHERE inhparent = c.oid"
            + "  UNION"
            + "  SELECT c.oid"
            + " )"
            + ") AS cardinality,"
            + "  a.attnum AS ordinal_position,"
            + "  t.typname AS type_name,"
            + "  information_schema._pg_char_max_length(a.atttypid, a.atttypmod) AS type_length,"
            + "  ico.collation_name AS collation,"
            + "  ico.pad_attribute AS pad,"
            + "  pg_encoding_to_char(d.encoding) AS charset,"
            + "  isc.numeric_scale AS numeric_scale,"
            + "  isc.datetime_precision AS datetime_precision"
            + " FROM pg_catalog.pg_indexes ixs"
            + "  JOIN pg_catalog.pg_class c ON c.relname = ixs.indexname"
            + "  JOIN pg_catalog.pg_index ix ON c.oid = ix.indexrelid"
            + "  JOIN pg_catalog.pg_attribute a ON c.oid = a.attrelid"
            + "  JOIN pg_catalog.pg_type t ON t.oid = a.atttypid"
            + "  LEFT OUTER JOIN pg_catalog.pg_collation co ON co.oid = ix.indcollation[a.attnum - 1]"
            + "  LEFT OUTER JOIN information_schema.collations ico ON ico.collation_name = co.collname"
            + "  LEFT OUTER JOIN pg_catalog.pg_database d ON d.datname = current_database()"
            + "  LEFT OUTER JOIN information_schema.columns isc ON isc.table_schema = ixs.schemaname AND isc.table_name = ixs.tablename AND isc.column_name = a.attname"
            + " WHERE ixs.schemaname = ?"
            + "  AND ixs.tablename IN "
            + DialectAdapter.generateInClause(tables.size())
            + " ORDER BY ix.indexrelid, ordinal_position ASC;";

    Map<String, ImmutableList.Builder<SourceColumnIndexInfo>> builders = new HashMap<>();
    tables.forEach(table -> builders.put(table, ImmutableList.builder()));

    try (Connection conn = dataSource.getConnection();
        PreparedStatement statement = conn.prepareStatement(query)) {
      statement.setFetchSize(1000);
      statement.setString(1, sourceSchemaReference.namespace());
      for (int i = 0; i < tables.size(); i++) {
        statement.setString(i + 2, tables.get(i));
      }
      try (ResultSet resultSet = statement.executeQuery()) {
        while (resultSet.next()) {
          final String tableName = resultSet.getString("table_name");
          final String typeName =
              Objects.requireNonNull(resultSet.getString("type_name"), "type_name is null");
          final String columnName = resultSet.getString("column_name");
          if (CUSTOM_BOUNDARY_QUERY_TYPES.contains(typeName.toUpperCase())) {
            customBoundaryQueryColumnKeys.add(new ColumnKey(tableName, columnName));
          }
          SourceColumnIndexInfo.IndexType indexType =
              INDEX_TYPE_MAPPING.getOrDefault(
                  typeName.toUpperCase(), SourceColumnIndexInfo.IndexType.OTHER);
          SourceColumnIndexInfo.Builder indexBuilder =
              SourceColumnIndexInfo.builder()
                  .setColumnName(columnName)
                  .setIndexName(resultSet.getString("index_name"))
                  .setIsUnique(resultSet.getBoolean("is_unique"))
                  .setIsPrimary(resultSet.getBoolean("is_primary"))
                  .setCardinality(resultSet.getLong("cardinality"))
                  .setOrdinalPosition(resultSet.getLong("ordinal_position"))
                  .setColumnTypeName(typeName)
                  .setIndexType(indexType);

          switch (indexType) {
            case FLOAT -> indexBuilder.setDecimalStepSize(new BigDecimal("0.00001"));
            case DOUBLE -> indexBuilder.setDecimalStepSize(new BigDecimal("0.0000000001"));
            case DECIMAL -> {
              long numericScale = resultSet.getLong("numeric_scale");
              indexBuilder.setNumericScale(resultSet.wasNull() ? 0 : (int) numericScale);
            }
            case DURATION, TIME_STAMP, LOCAL_TIME, OFFSET_TIME -> {
              long datetimePrecision = resultSet.getLong("datetime_precision");
              // Postgres default precision for time is microseconds (6)
              indexBuilder.setDatetimePrecision(resultSet.wasNull() ? 6 : (int) datetimePrecision);
            }
            default -> {}
          }

          String collation = resultSet.getString("collation");
          if (collation != null) {
            String charset = resultSet.getString("charset");
            Integer typeLength = resultSet.getInt("type_length");
            if (resultSet.wasNull()) {
              typeLength = null;
            }
            // Collation PAD SPACE is not supported in Postgresql
            // (https://www.postgresql.org/docs/current/infoschema-collations.html)
            // The only way to have blank space padding is for specific types with fixed length
            // (https://www.postgresql.org/docs/current/datatype-character.html)
            boolean shouldPadSpace = isBlankPaddedType(typeName, typeLength);
            indexBuilder.setCollationReference(
                CollationReference.builder()
                    .setDbCharacterSet(charset)
                    .setDbCollation(collation)
                    .setPadSpace(shouldPadSpace)
                    .build());
            indexBuilder.setStringMaxLength(typeLength == null ? VARCHAR_MAX_LENGTH : typeLength);
          }
          if (builders.containsKey(tableName)) {
            builders.get(tableName).add(indexBuilder.build());
          }
        }
      }
    } catch (SQLTransientConnectionException e) {
      logger.warn(
          "Transient connection error while discovering table indexes for datasource={} db={} tables={}",
          dataSource,
          sourceSchemaReference,
          tables,
          e);
      schemaDiscoveryErrors.inc();
      throw new RetriableSchemaDiscoveryException(e);
    } catch (SQLNonTransientConnectionException e) {
      logger.error(
          "Non Transient connection error while discovering table indexes for datasource={}, db={} tables={}",
          dataSource,
          sourceSchemaReference,
          tables,
          e);
      schemaDiscoveryErrors.inc();
      throw new SchemaDiscoveryException(e);
    } catch (SQLException e) {
      logger.error(
          "Sql exception while discovering table schema for datasource={} db={} tables={}",
          dataSource,
          sourceSchemaReference,
          tables,
          e);
      schemaDiscoveryErrors.inc();
      throw new SchemaDiscoveryException(e);
    }

    ImmutableMap.Builder<String, ImmutableList<SourceColumnIndexInfo>> result =
        ImmutableMap.builder();
    builders.forEach((table, builder) -> result.put(table, builder.build()));

    ImmutableMap<String, ImmutableList<SourceColumnIndexInfo>> tableIndexes = result.build();
    logger.info(
        "Discovered Indexes for DataSource: {}, JdbcSchemaReference: {}, Tables: {}",
        dataSource,
        sourceSchemaReference,
        tables);
    return tableIndexes;
  }

static void handleDatastreamRecordType(
        String fieldName, Schema fieldSchema, GenericRecord element, ObjectNode jsonObject) {
      switch (fieldSchema.getName()) {
        case "Json":
          jsonObject.put(fieldName, element.toString());
          break;
        case "varchar":
          // TODO(pabloem): Remove this after Datastream rollout N+1 after 2020-10-26
          // Datastream Varchars are represented with their value and length.
          // For us, we only care about values.
          element.get("value");
          jsonObject.put(fieldName, element.get("value").toString());
          break;
        case "calendarDate":
          LocalDate date =
              LocalDate.of(
                  (Integer) element.get("year"),
                  (Integer) element.get("month"),
                  (Integer) element.get("day"));
          jsonObject.put(fieldName, date.format(DEFAULT_DATE_FORMATTER));
          break;
        case "year":
          jsonObject.put(fieldName, (Integer) element.get("year"));
          break;
        case "timestampTz":
          // Timestamp comes in microseconds
          Long nanoseconds = (Long) element.get("timestamp") * TimeUnit.MICROSECONDS.toNanos(1);
          Instant timestamp =
              Instant.ofEpochSecond(
                  TimeUnit.NANOSECONDS.toSeconds(nanoseconds),
                  nanoseconds % TimeUnit.SECONDS.toNanos(1));
          // Offset comes in milliseconds
          ZoneOffset offset =
              ZoneOffset.ofTotalSeconds(((Number) element.get("offset")).intValue() / 1000);
          ZonedDateTime fullDate = timestamp.atOffset(offset).toZonedDateTime();
          // BigQuery only has UTC timestamps so we convert to UTC and adjust
          jsonObject.put(
              fieldName,
              fullDate
                  .withZoneSameInstant(ZoneId.of("UTC"))
                  .format(DEFAULT_TIMESTAMP_WITH_TZ_FORMATTER));
          break;
        case "timeTz":
          long timeTzNanos =
              ((Number) getOrDefault(element, "time", 0L)).longValue()
                  * TimeUnit.MICROSECONDS.toNanos(1);
          int offsetSeconds = ((Number) getOrDefault(element, "offset", 0)).intValue() / 1000;

          ZoneOffset timeTzOffset = ZoneOffset.ofTotalSeconds(offsetSeconds);

          if (timeTzNanos == 86400000000000L) {
            jsonObject.put(fieldName, "24:00:00" + timeTzOffset.toString());
            break;
          }

          LocalTime localTime = LocalTime.ofNanoOfDay(timeTzNanos);
          OffsetTime offsetTime = OffsetTime.of(localTime, timeTzOffset);
          jsonObject.put(fieldName, offsetTime.format(DateTimeFormatter.ISO_OFFSET_TIME));
          break;
        case "interval":
          int months = ((Number) getOrDefault(element, "months", 0)).intValue();
          int hours = ((Number) getOrDefault(element, "hours", 0)).intValue();
          long micros = ((Number) getOrDefault(element, "micros", 0L)).longValue();

          int days = hours / 24;
          int remainingHours = hours % 24;

          Period intervalPeriod = Period.ZERO.plusMonths(months).plusDays(days).normalized();
          Duration intervalDuration =
              Duration.ZERO.plusHours(remainingHours).plus(micros, ChronoUnit.MICROS);

          if (intervalPeriod.isZero() && intervalDuration.isZero()) {
            jsonObject.put(fieldName, "PT0S");
            break;
          }

          StringBuilder result = new StringBuilder();
          if (!intervalPeriod.isZero()) {
            result.append(intervalPeriod.toString());
          }
          if (!intervalDuration.isZero()) {
            if (result.length() == 0) {
              result.append(intervalDuration.toString());
            } else {
              // Remove the 'P' from Duration
              result.append(intervalDuration.toString().substring(1));
            }
          }
          jsonObject.put(fieldName, result.toString());
          break;
          /*
           * The `intervalNano` maps to nano second precision interval type used by Cassandra Interval.
           * On spanner this will map to `string` or `Interval` type.
           * This is added here for DQL retrials for sourcedb-to-spanner.
           *
           * TODO(b/383689307):
           * There's a lot of commonality in handling avro types between {@link FormatDatastreamRecordToJson} and {@link com.google.cloud.teleport.v2.spanner.migrations.avro.GenericRecordTypeConvertor}.
           * Adding inter-package dependency might not be the best route, and we might eventually want to build a common package for handling common logic between the two.
           */
        case "intervalNano":
          Period period =
              Period.ZERO
                  .plusYears(getOrDefault(element, "years", 0L))
                  .plusMonths(getOrDefault(element, "months", 0L))
                  .plusDays(getOrDefault(element, "days", 0L));
          /*
           * Convert the period to a ISO-8601 period formatted String, such as P6Y3M1D.
           * A zero period will be represented as zero days, 'P0D'.
           * Refer to javadoc for Period#toString.
           */
          String periodIso8061 = period.toString();
          java.time.Duration duration =
              java.time.Duration.ZERO
                  .plusHours(getOrDefault(element, "hours", 0L))
                  .plusMinutes(getOrDefault(element, "minutes", 0L))
                  .plusSeconds(getOrDefault(element, "seconds", 0L))
                  .plusNanos(getOrDefault(element, "nanos", 0L));
          /*
           * Convert the duration to a ISO-8601 period formatted String, such as  PT8H6M12.345S
           * refer to javadoc for Duration#toString.
           */
          String durationIso8610 = duration.toString();
          // Convert to ISO-8601 period format.
          String convertedIntervalNano;
          if (duration.isZero()) {
            convertedIntervalNano = periodIso8061;
          } else {
            convertedIntervalNano =
                periodIso8061 + StringUtils.removeStartIgnoreCase(durationIso8610, "P");
          }
          jsonObject.put(fieldName, convertedIntervalNano);
          break;
        default:
          ObjectMapper mapper = new ObjectMapper();
          JsonNode dataInput;
          try {
            dataInput = mapper.readTree(element.toString());
            jsonObject.put(fieldName, dataInput);
          } catch (IOException e) {
            LOG.error("Issue parsing JSON record. Unable to continue.", e);
            throw new RuntimeException(e);
          }
          break;
      }
    }

@Override
  public ImmutableMap<String, ImmutableList<SourceColumnIndexInfo>> discoverTableIndexes(
      DataSource dataSource,
      JdbcSchemaReference sourceSchemaReference,
      ImmutableList<String> tables)
      throws SchemaDiscoveryException, RetriableSchemaDiscoveryException {
    if (tables.isEmpty()) {
      return ImmutableMap.of();
    }
    LOGGER.info(
        String.format(
            "Discovering Indexes for JdbcSchemaReference: %s, Tables: %s",
            sourceSchemaReference, tables));
    // Simplified index discovery for SQL Server. Focus on primary keys.
    String query =
        "SELECT "
            + "    t.name AS table_name, "
            + "    ind.name AS index_name, "
            + "    col.name AS column_name, "
            + "    ic.key_ordinal AS ordinal_position, "
            + "    ind.is_unique, "
            + "    ind.is_primary_key AS is_primary, "
            + "    ty.name AS type_name, "
            + "    col.max_length AS max_length, "
            + "    col.scale AS scale, "
            + "    col.collation_name AS collation_name, "
            + "    ISNULL(p.rows, 0) AS cardinality "
            + "FROM sys.indexes ind "
            + "INNER JOIN sys.index_columns ic ON ind.object_id = ic.object_id and ind.index_id = ic.index_id "
            + "INNER JOIN sys.columns col ON ic.object_id = col.object_id and ic.column_id = col.column_id "
            + "INNER JOIN sys.tables t ON ind.object_id = t.object_id "
            + "INNER JOIN sys.types ty ON col.system_type_id = ty.system_type_id AND col.user_type_id = ty.user_type_id "
            + "LEFT JOIN (SELECT object_id, index_id, SUM(rows) AS rows FROM sys.partitions GROUP BY object_id, index_id) p ON ind.object_id = p.object_id AND ind.index_id = p.index_id "
            + "WHERE SCHEMA_NAME(t.schema_id) = ? "
            + "AND ic.is_included_column = 0 "
            + "AND ind.is_disabled = 0 "
            + "AND ind.is_hypothetical = 0 "
            + "AND t.name IN "
            + DialectAdapter.generateInClause(tables.size());

    Map<String, ImmutableList.Builder<SourceColumnIndexInfo>> builders = new HashMap<>();
    tables.forEach(table -> builders.put(table, ImmutableList.builder()));

    try (Connection conn = dataSource.getConnection();
        PreparedStatement stmt = conn.prepareStatement(query)) {
      stmt.setString(1, getNamespace(sourceSchemaReference));
      for (int i = 0; i < tables.size(); i++) {
        stmt.setString(i + 2, tables.get(i));
      }
      try (ResultSet rs = stmt.executeQuery()) {
        while (rs.next()) {
          String tableName = rs.getString("table_name");
          String typeName = rs.getString("type_name");
          String upperType = typeName.toUpperCase();
          IndexType indexType = INDEX_TYPE_MAPPING.getOrDefault(upperType, IndexType.OTHER);

          SourceColumnIndexInfo.Builder infoBuilder =
              SourceColumnIndexInfo.builder()
                  .setColumnName(rs.getString("column_name"))
                  .setIndexName(rs.getString("index_name"))
                  .setIsUnique(rs.getBoolean("is_unique"))
                  .setIsPrimary(rs.getBoolean("is_primary"))
                  .setOrdinalPosition(rs.getLong("ordinal_position"))
                  .setCardinality(rs.getLong("cardinality"))
                  .setColumnTypeName(typeName)
                  .setIndexType(indexType);

          if (indexType == SourceColumnIndexInfo.IndexType.STRING) {
            boolean padSpace = upperType.equals("CHAR") || upperType.equals("NCHAR");
            String collationName = rs.getString("collation_name");
            if (collationName == null || collationName.isEmpty()) {
              collationName = "Latin1_General_BIN";
            }
            CollationReference collation =
                CollationReference.builder()
                    .setDbCharacterSet("UTF8")
                    .setDbCollation(collationName)
                    .setPadSpace(padSpace)
                    .build();
            infoBuilder.setCollationReference(collation);
            int maxLength = rs.getInt("max_length");
            if (maxLength <= 0) {
              maxLength = 255;
            } else if (upperType.startsWith("N")) {
              maxLength = maxLength / 2;
            }
            infoBuilder.setStringMaxLength(maxLength);
          } else if (indexType == SourceColumnIndexInfo.IndexType.DECIMAL) {
            infoBuilder.setNumericScale(rs.getInt("scale"));
          }

          if (builders.containsKey(tableName)) {
            builders.get(tableName).add(infoBuilder.build());
          }
        }
      }
    } catch (SQLTransientConnectionException e) {
      LOGGER.warn(
          String.format(
              "Transient connection error while discovering table indexes for db=%s tables=%s, cause=%s",
              sourceSchemaReference, tables, e));
      schemaDiscoveryErrors.inc();
      throw new RetriableSchemaDiscoveryException(e);
    } catch (SQLNonTransientConnectionException e) {
      LOGGER.error(
          String.format(
              "Non Transient connection error while discovering table indexes for db=%s tables=%s, cause=%s",
              sourceSchemaReference, tables, e));
      schemaDiscoveryErrors.inc();
      throw new SchemaDiscoveryException(e);
    } catch (SQLException e) {
      LOGGER.error(
          String.format(
              "Sql exception while discovering table indexes for db=%s tables=%s, cause=%s",
              sourceSchemaReference, tables, e));
      schemaDiscoveryErrors.inc();
      throw new SchemaDiscoveryException(e);
    } catch (SchemaDiscoveryException e) {
      LOGGER.error(
          String.format(
              "Schema discovery exception while discovering table indexes for db=%s tables=%s, cause=%s",
              sourceSchemaReference, tables, e));
      schemaDiscoveryErrors.inc();
      throw e;
    }

    ImmutableMap.Builder<String, ImmutableList<SourceColumnIndexInfo>> result =
        ImmutableMap.builder();
    builders.forEach((t, b) -> result.put(t, b.build()));
    return result.build();
  }
